<?php
defined('ABSPATH')||exit; class CFP_Email_Engine{public function send_template(int $id,array $vars):bool{return $this->send(get_bloginfo('admin_email'),'ConversionFlow Pro',CFP_Email_Templates::render('default',$vars),$vars);} public function send(string $to,string $subject,string $body,array $vars=array()):bool{$body=$this->replace($body,$vars); $ok=wp_mail(sanitize_email($to),wp_strip_all_tags($this->replace($subject,$vars)),$body,array('Content-Type: text/html; charset=UTF-8')); (new CFP_Email_Logger())->log($to,$subject,$ok?'sent':'failed'); return $ok;} private function replace(string $text,array $vars):string{foreach(array('customer_name','customer_email','order_id','order_total','product_name','download_link','funnel_name','checkout_url','site_name') as $k){$text=str_replace('{'.$k.'}',esc_html((string)($vars[$k]??($k==='site_name'?get_bloginfo('name'):''))),$text);} return $text;}}
